/* CSS placed here will be applied to all skins */

/* Additions for Zweig Bibliography
 * modifications by David Klawiter (klawiter@nd.edu)
*/ 

#ca-talk, #ca-history, #ca-viewsource {
 display: none!important;
}

ol {
 line-height: 1.5em;
 margin: .3em 0 0 3.2em;
 padding: 0;
 list-style-image: none;
 list-style-type: decimal;
}

ol ol {
 line-height: 1.5em;
 margin: .3em 0 0 3.2em;
 padding: 0;
 list-style-image: none;
 list-style-type: lower-alpha;
}

ol ol ol {
 line-height: 1.5em;
 margin: .3em 0 0 3.2em;
 padding: 0;
 list-style-image: none;
 list-style-type: lower-roman;
}

.zweigSubHeading0{
 margin-left: -3.25em;
 /* this puts the text to the left margin */
 line-height: 2.25em;
 position:relative;
 top: 0.25em;
}

.zweigSubHeading10{
 margin-left: -3.25em;
 /* this puts the text to the left margin */
}

.zweigSubHeading1{
 margin-left: .7em;
 /* used for first entry (before start of number list) */
 line-height: 1.75em;
 position:relative;
 top: 0.4em;
}

.zweigSubHeading11{
 margin-left: .7em;
 /* used for first entry (before start of number list) */
}

.zweigSubHeading2{
 margin-left: -2.5em;
 /* used for entries inside of a number list */
 line-height: 2.25em;
 position:relative;
 top: 0.25em;
}

.zweigSubHeading12{
 margin-left: -2.5em;
 /* used for entries inside of a number list */
}

.zweigSubHeading3{
 line-height: 2em;
 position:relative;
 top: 0.25em;
}

.level1 {
 width: 3em;
 text-align: right;
}
.level2 {
 width: 6em;
 text-align: right;
}
.level3 {
 width: 9em;
 text-align: right;
}
.level4 {
 width: 12em;
 text-align: right;
}
.level5 {
 width: 15em;
 text-align: right;
}

.cell {
 padding-left: 5px;
}

div.cell,
div.level1,
div.level2,
div.level3,
div.level4,
div.level5 {
 display: table-cell;
}

.row { display: table-row; }

.rowsep {margin: 0; padding: 0; height: 0px; }

.indent1 {
 margin-left: 3.4em;
}
.indent2 {
 margin-left: 6.4em;
}
.indent3 {
 margin-left: 9.4em;
}
.indent4 {
 margin-left: 12.4em;
}
.indent5 {
 margin-left: 15.4em;
}

.bracketsep {margin: 0; padding: 0; height: 1em; }
